package org.joda.time.chrono;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeConstants;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeZone;
import org.joda.time.DurationField;
import org.joda.time.IllegalFieldValueException;
import org.joda.time.Instant;
import org.joda.time.ReadablePartial;
import org.joda.time.field.BaseDateTimeField;
import org.joda.time.field.BaseDurationField;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ZonedDateTimeField.set(long, String, Locale)
 */
public class ZonedDateTimeField_set_TriageGen0Test {

    private org.joda.time.chrono.ZonedChronology.ZonedDateTimeField field;
    private DateTimeZone zone;

    @Before
    public void setUp() {
        // Using UTC for a controlled environment to test the logic of the set method
        zone = DateTimeZone.UTC;
        // We need an instance of ZonedDateTimeField. 
        // Since it is an inner class, we access it via a ZonedChronology instance.
        org.joda.time.chrono.ZonedChronology chronology = org.joda.time.chrono.DateTimeChronology.getChronology(zone);
        // We use a dummy DateTime to get a field instance that represents a specific field (e.g., Year)
        // However, the prompt implies testing the method directly on the provided signature.
        // In Joda-Time, ZonedDateTimeField is an inner class. For testing purposes, we simulate the behavior.
        // Since we cannot instantiate the private inner class easily without reflection or a real Chronology,
        // we use a real Chronology instance to get a valid field.
        field = (org.joda.time.chrono.ZonedChronology.ZonedDateTimeField) chronology.getDateTimeFields().getYear();
    }

    @Test
    public void testSet_ValidYear_ReturnsCorrectInstant() {
        long instant = DateTime.getInstance(zone).getMillis();
        String text = "2025";
        Locale locale = Locale.ENGLISH;

        long resultInstant = field.set(instant, text, locale);

        DateTime dt = new DateTime(resultInstant, zone);
        Assert.assertEquals(2025, dt.getYear());
    }

    @Test
    public void testSet_WithLocaleSpecificText_ReturnsCorrectInstant() {
        long instant = DateTime.getInstance(zone).getMillis();
        // Using a locale that might represent numbers/text differently if applicable, 
        // but for Year, English is standard.
        String text = "2030";
        Locale locale = Locale.GERMANY;

        long resultInstant = field.set(instant, text, locale);

        DateTime dt = new DateTime(resultInstant, zone);
        Assert.assertEquals(2030, dt.getYear());
    }

    @Test
    public void testSet_LenientBehavior_HandlesOverflow() {
        // If the field is Year, setting a value like "2025" is straightforward.
        // The method documentation says "set may be lenient".
        long instant = DateTime.getInstance(zone).getMillis();
        String text = "2025";
        Locale locale = Locale.ENGLISH;

        long resultInstant = field.set(instant, text, locale);

        // Verify that the result is indeed the start of the year 2025 in UTC
        DateTime dt = new DateTime(resultInstant, zone);
        Assert.assertEquals(2025, dt.getYear());
        Assert.assertEquals(0, dt.getMonthOfYear()); // Joda months are 1-12, but we check via dt.getYear()
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSet_InvalidText_ThrowsException() {
        long instant = DateTime.getInstance(zone).getMillis();
        String text = "not-a-year";
        Locale locale = Locale.ENGLISH;

        field.set(instant, text, locale);
    }

    @Test
    public void testSet_PreservesOtherFields() {
        // Set a specific date: 2020-05-15
        DateTime original = new DateTime(2020, 5, 15, 12, 0, 0, zone);
        long instant = original.getMillis();

        // Change only the year using the field
        String text = "2025";
        long resultInstant = field.set(instant, text, Locale.ENGLISH);

        DateTime resultDt = new DateTime(resultInstant, zone);

        Assert.assertEquals(2025, resultDt.getYear());
        Assert.assertEquals(5, resultDt.getMonthOfYear());
        Assert.assertEquals(15, resultDt.getDayOfMonth());
        Assert.assertEquals(12, resultDt.getHourOfDay());
    }

    @Test
    public void testSet_LargeInstant() {
        // Test with a very large instant (far future)
        long instant = DateTime.getInstance(zone).getMillis();
        String text = "9999";
        long resultInstant = field.set(instant, text, Locale.ENGLISH);

        DateTime dt = new DateTime(resultInstant, zone);
        Assert.assertEquals(9999, dt.getYear());
    }
}
